/**
 * Browser-side process simulator (AmCraX Phase 2). Public API.
 *
 * Data: snapshot/simulator/{model,aspen_anchors}.json, copied by scripts/export_snapshot.py from
 * results/research/simulator/ (generated by scripts/research/export_simulator_data.py). Fetched at run time relative
 * to import.meta.env.BASE_URL, so it works under base '/' (dev) and '/AmCraX/' (GitHub Pages).
 */
import { withBase } from '../api/url'
import type { SimAnchors, SimData, SimModel } from './types'

export * from './types'
export { simulate, ROUTE_PRICE_SCENARIO, type SimInputs, type SimOutputs, type NH3Route } from './simulate'
export { simulatePFR, type PFRInputs, type PFRResult, type ThermalMode } from './pfr'
export { simulateProcess, type ProcessInputs, type ProcessResult } from './process'
export { catalystPrice, evaluateEconomics, type CostKey, type EconResult, type EconSummary, type EconOverrides } from './economics'
export { carbonIntensity, carbonCost, crossoverPrice, type CIResult, type CarbonCost, type Heating } from './carbon'
export { rate, law } from './kinetics'
export { equilibriumConversion, equilibriumConstant, reactionEnthalpy } from './thermo'
export { findKineticAnchor, findCoreAnchor, aspenEquilibrium } from './anchors'
export { inputRanges, domainWarnings, type Range } from './domain'
export * as sweeps from './sweeps'
export { lhvEfficiency, inletOutletRate } from './kpis'

let cache: Promise<SimData> | null = null

/** Fetch model.json and aspen_anchors.json once (paths through src/api/url.ts withBase: '/' dev, '/AmCraX/' Pages). */
export function loadSimulatorData(base?: string): Promise<SimData> {
  if (cache) return cache
  const get = async <T>(n: string): Promise<T> => {
    const r = await fetch(base === undefined ? withBase(`/snapshot/simulator/${n}`) : withBase(`/snapshot/simulator/${n}`, base))
    if (!r.ok) throw new Error(`simulator data ${n}: HTTP ${r.status}`)
    return (await r.json()) as T
  }
  cache = Promise.all([get<SimModel>('model.json'), get<SimAnchors>('aspen_anchors.json')]).then(([model, anchors]) => ({ model, anchors }))
  cache.catch(() => { cache = null })
  return cache
}
